import http from 'node:http';
const PORT = Number(process.env.PORT || 5000);

const SPORT = {
  nfl: { sport: 'football', league: 'nfl', label: 'NFL' },
  nba: { sport: 'basketball', league: 'nba', label: 'NBA' },
  mlb: { sport: 'baseball', league: 'mlb', label: 'MLB' },
};

const cache = new Map();
function cacheGet(key, ttlMs) {
  const item = cache.get(key);
  if (!item || Date.now() - item.time > ttlMs) return null;
  return item.value;
}
function cacheSet(key, value) { cache.set(key, { value, time: Date.now() }); return value; }

async function fetchJSON(url, timeoutMs = 9000) {
  const r = await fetch(url, {
    headers: {
      'accept': 'application/json,text/plain,*/*',
      'user-agent': 'node-fetch',
    },
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (!r.ok) throw new Error(`ESPN request failed (${r.status})`);
  return r.json();
}

function espnBase(key) {
  const c = SPORT[key];
  if (!c) throw new Error('Unsupported sport');
  return `https://site.api.espn.com/apis/site/v2/sports/${c.sport}/${c.league}`;
}

function firstCompetition(event) { return event?.competitions?.[0] || null; }
function competitors(comp) {
  const arr = comp?.competitors || [];
  return {
    home: arr.find(x => x.homeAway === 'home') || arr[0] || {},
    away: arr.find(x => x.homeAway === 'away') || arr[1] || {},
  };
}
function recordOf(c) {
  return c?.records?.find(r => r.type === 'total' || r.name === 'overall')?.summary ||
    c?.record?.summary || '—';
}
function teamOf(c) {
  return {
    id: String(c?.team?.id || c?.id || ''),
    name: c?.team?.displayName || c?.team?.name || c?.displayName || 'Unknown',
    abbreviation: c?.team?.abbreviation || c?.abbreviation || '',
    logo: c?.team?.logo || c?.team?.logos?.[0]?.href || c?.logo || '',
    record: recordOf(c),
  };
}

function parseAmerican(v) {
  if (v == null) return null;
  const n = Number(String(v).replace('+', '').trim());
  if (!Number.isFinite(n) || n === 0) return null;
  return n < 0 ? (-n) / ((-n) + 100) : 100 / (n + 100);
}
function noVig(homeOdds, awayOdds) {
  const h = parseAmerican(homeOdds), a = parseAmerican(awayOdds);
  if (h == null || a == null || h + a <= 0) return null;
  const hp = h / (h + a);
  return { home: Math.round(hp * 100), away: Math.round((1 - hp) * 100) };
}
function pctFromRecord(record) {
  const m = String(record || '').match(/(\d+)-(\d+)(?:-(\d+))?/);
  if (!m) return null;
  const w = +m[1], l = +m[2], t = +(m[3] || 0), g = w + l + t;
  return g ? (w + 0.5 * t) / g : null;
}

function oddsInfo(comp) {
  const o = comp?.odds?.[0] || null;
  if (!o) return { raw: null, provider: null, spread: null, total: null, money: null };
  const provider = o?.provider?.displayName || o?.provider?.name || 'ESPN Odds';
  const spreadNum = Number(o?.spread);
  const overUnder = Number(o?.overUnder);
  const homeML = o?.moneyline?.home?.close?.odds ?? o?.homeTeamOdds?.moneyLine ?? o?.homeTeamOdds?.moneyline ?? null;
  const awayML = o?.moneyline?.away?.close?.odds ?? o?.awayTeamOdds?.moneyLine ?? o?.awayTeamOdds?.moneyline ?? null;
  return {
    raw: o,
    provider,
    spread: Number.isFinite(spreadNum) ? { home: { line: spreadNum }, away: { line: -spreadNum } } : null,
    total: Number.isFinite(overUnder) ? { line: overUnder } : null,
    money: noVig(homeML, awayML),
  };
}

function fallbackProbability(home, away, spread) {
  if (spread?.home?.line != null) {
    // Approximate a moneyline-like probability from point spread.
    const hp = 1 / (1 + Math.exp(Number(spread.home.line) * 0.17));
    const rounded = Math.max(5, Math.min(95, Math.round(hp * 100)));
    return { home: rounded, away: 100 - rounded };
  }
  const hr = pctFromRecord(home.record), ar = pctFromRecord(away.record);
  if (hr != null && ar != null && hr + ar > 0) {
    const raw = (hr + 0.04) / (hr + ar + 0.08); // small home-field nudge
    const hp = Math.max(10, Math.min(90, Math.round(raw * 100)));
    return { home: hp, away: 100 - hp };
  }
  return { home: 50, away: 50 };
}

async function liveProbability(key, eventId) {
  try {
    const summary = await fetchJSON(`${espnBase(key)}/summary?event=${encodeURIComponent(eventId)}`, 7000);
    const wp = summary?.winprobability;
    if (Array.isArray(wp) && wp.length) {
      const last = wp[wp.length - 1];
      const h = Number(last?.homeWinPercentage);
      const tie = Number(last?.tiePercentage || 0);
      if (Number.isFinite(h)) {
        const home = Math.round(h * 100);
        const away = Math.max(0, 100 - home - Math.round(tie * 100));
        return { home, away, source: 'ESPN Live Model', summary };
      }
    }
    return { source: null, summary };
  } catch {
    return { source: null, summary: null };
  }
}

function eventMeta(event, comp, key) {
  const venue = comp?.venue;
  const loc = venue?.address ? [venue.address.city, venue.address.state].filter(Boolean).join(', ') : '';
  const broadcast = comp?.broadcast || comp?.broadcasts?.[0]?.names?.[0] || '';
  const state = comp?.status?.type?.state || event?.status?.type?.state || 'pre';
  return {
    id: String(event?.id || comp?.id || ''),
    startDate: event?.date || comp?.date || new Date().toISOString(),
    seasonWeek: event?.week?.number ? `Week ${event.week.number}` : SPORT[key].label,
    isLive: state === 'in',
    isFinal: state === 'post' || !!comp?.status?.type?.completed,
    venue: venue?.fullName || '',
    venueLocation: loc,
    broadcast,
  };
}

async function transformEvent(key, event, includeLive = true) {
  const comp = firstCompetition(event);
  if (!comp) return null;
  const { home: hc, away: ac } = competitors(comp);
  const home = teamOf(hc), away = teamOf(ac);
  const meta = eventMeta(event, comp, key);
  const oi = oddsInfo(comp);
  let prediction = oi.money || fallbackProbability(home, away, oi.spread);
  let books = oi.provider ? [oi.provider] : [];

  if (includeLive && meta.isLive) {
    const live = await liveProbability(key, meta.id);
    if (live.home != null) {
      prediction = { home: live.home, away: live.away };
      books = [live.source];
    }
  }

  return {
    ...meta,
    home,
    away,
    prediction: { ...prediction, books },
    spread: oi.spread,
    total: oi.total,
  };
}

async function getScoreboard(key) {
  const ck = `score:${key}`;
  const hit = cacheGet(ck, 30000);
  if (hit) return hit;
  return cacheSet(ck, await fetchJSON(`${espnBase(key)}/scoreboard`));
}

async function getMatchups(key) {
  const score = await getScoreboard(key);
  const raw = Array.isArray(score?.events) ? score.events : [];
  const items = (await Promise.all(raw.map(e => transformEvent(key, e, true)))).filter(Boolean);
  const providers = [...new Set(items.flatMap(x => x.prediction?.books || []))];
  return { matchups: items, sportsbooks: providers, lastUpdated: new Date().toISOString() };
}

function statMap(stats) {
  const out = {};
  for (const s of stats || []) {
    const key = s?.name || s?.abbreviation || s?.displayName;
    if (key) out[key] = s?.value ?? s?.displayValue;
  }
  return out;
}
function num(v, fallback = 0) {
  const n = Number(String(v ?? '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : fallback;
}

function collectStandingEntries(node, out = []) {
  if (!node || typeof node !== 'object') return out;
  if (Array.isArray(node?.standings?.entries)) {
    out.push(...node.standings.entries);
  }
  for (const [k, v] of Object.entries(node)) {
    if (k === 'standings') continue;
    if (Array.isArray(v)) v.forEach(x => collectStandingEntries(x, out));
    else if (v && typeof v === 'object') collectStandingEntries(v, out);
  }
  return out;
}

async function getStandingsRaw(key) {
  const c = SPORT[key];
  const ck = `standraw:${key}`;
  const hit = cacheGet(ck, 60000);
  if (hit) return hit;
  const url = `https://site.api.espn.com/apis/v2/sports/${c.sport}/${c.league}/standings`;
  return cacheSet(ck, await fetchJSON(url));
}
function normalizeStanding(entry) {
  const sm = statMap(entry?.stats);
  const wins = num(sm.wins ?? sm.W ?? entry?.wins);
  const losses = num(sm.losses ?? sm.L ?? entry?.losses);
  const ties = num(sm.ties ?? sm.T ?? entry?.ties);
  const gp = Math.max(0, wins + losses + ties);
  let winPct = Number(sm.winPercent ?? sm.winPercentage);
  if (!Number.isFinite(winPct)) winPct = gp ? (wins + 0.5 * ties) / gp : 0;
  const pointsFor = num(sm.pointsFor ?? sm.PF);
  const pointsAgainst = num(sm.pointsAgainst ?? sm.PA);
  const team = entry?.team || {};
  return {
    id: String(team.id || ''),
    name: team.displayName || team.name || 'Unknown',
    abbreviation: team.abbreviation || '',
    logo: team.logos?.[0]?.href || team.logo || '',
    wins, losses, ties, winPct,
    pointsFor, pointsAgainst,
    diff: num(sm.pointDifferential, pointsFor - pointsAgainst),
    gamesPlayed: gp,
  };
}
async function getStandings(key) {
  const raw = await getStandingsRaw(key);
  const entries = collectStandingEntries(raw);
  const seen = new Set();
  const standings = entries.map(normalizeStanding).filter(x => x.name !== 'Unknown' && !seen.has(x.id) && seen.add(x.id));
  standings.sort((a, b) => b.winPct - a.winPct || b.diff - a.diff);
  return { standings, lastUpdated: new Date().toISOString() };
}

function leaderPlayers(comp, side, key) {
  const { home, away } = competitors(comp);
  const c = side === 'home' ? home : away;
  const result = new Map();
  const leaders = c?.leaders || [];
  for (const group of leaders) {
    const lead = group?.leaders?.[0];
    const a = lead?.athlete;
    if (!a) continue;
    const name = a.displayName || a.fullName;
    if (!result.has(name)) result.set(name, { name, position: a?.position?.abbreviation || '', stats: {}, edge: [] });
    const p = result.get(name);
    const text = lead?.displayValue || '';
    const val = Number(lead?.value) || 0;
    const g = String(group?.name || '').toLowerCase();
    if (key === 'nfl') {
      if (g.includes('passing')) { p.stats.passing_yards = Math.round(val); p.stats.passing_touchdowns = num((text.match(/(\d+)\s*TD/i)||[])[1]); }
      if (g.includes('rushing')) { p.stats.rushing_yards = Math.round(val); p.stats.rushing_touchdowns = num((text.match(/(\d+)\s*TD/i)||[])[1]); }
      if (g.includes('receiving')) { p.stats.receiving_yards = Math.round(val); p.stats.receptions = num((text.match(/(\d+)\s*REC/i)||[])[1]); p.stats.receiving_touchdowns = num((text.match(/(\d+)\s*TD/i)||[])[1]); }
    } else if (key === 'nba') {
      if (g.includes('points')) p.stats.points = Math.round(val);
      if (g.includes('rebounds')) p.stats.total_rebounds = Math.round(val);
      if (g.includes('assists')) p.stats.assists = Math.round(val);
    }
  }
  return [...result.values()].slice(0, 8);
}

async function recentGames(key, teamId) {
  if (!teamId) return [];
  try {
    const data = await fetchJSON(`${espnBase(key)}/teams/${teamId}/schedule`, 7000);
    const events = Array.isArray(data?.events) ? data.events : [];
    const done = events.filter(e => firstCompetition(e)?.status?.type?.completed).sort((a,b) => new Date(b.date) - new Date(a.date)).slice(0,3);
    return done.map(e => {
      const c = firstCompetition(e), cs = competitors(c);
      const me = String(cs.home?.team?.id) === String(teamId) ? cs.home : cs.away;
      const op = me === cs.home ? cs.away : cs.home;
      const myScore = num(me?.score), opScore = num(op?.score);
      return {
        result: myScore > opScore ? 'W' : myScore < opScore ? 'L' : 'T',
        week: e?.week?.number ? `Wk ${e.week.number}` : new Date(e.date).toLocaleDateString('en-US', { month:'short', day:'numeric' }),
        opponent: op?.team?.abbreviation || op?.team?.displayName || 'Opponent',
        teamScore: myScore,
        oppScore: opScore,
      };
    });
  } catch { return []; }
}

async function injuries(key, teamId) {
  if (!teamId) return [];
  try {
    const data = await fetchJSON(`${espnBase(key)}/teams/${teamId}/injuries`, 7000);
    let arr = data?.injuries || data?.team?.injuries || [];
    if (!Array.isArray(arr)) arr = [];
    return arr.slice(0,10).map(i => ({
      player: i?.athlete?.displayName || i?.athlete?.fullName || i?.displayName || 'Player',
      position: i?.athlete?.position?.abbreviation || i?.position?.abbreviation || '',
      type: i?.type?.description || i?.type?.name || i?.details?.type || i?.shortComment || '',
      status: i?.status || i?.details?.status || 'Questionable',
    }));
  } catch { return []; }
}

function analysisFor(standing, team) {
  if (standing?.gamesPlayed) {
    const off = standing.pointsFor / standing.gamesPlayed;
    const def = standing.pointsAgainst / standing.gamesPlayed;
    const form = `${standing.wins}-${standing.losses}${standing.ties ? `-${standing.ties}` : ''}`;
    return { offensiveAvg: Number(off.toFixed(1)), defensiveAvg: Number(def.toFixed(1)), recentForm: form, winRate: Number((standing.winPct * 100).toFixed(1)) };
  }
  const pct = pctFromRecord(team.record) || 0;
  return { offensiveAvg: 0, defensiveAvg: 0, recentForm: team.record || '—', winRate: Number((pct * 100).toFixed(1)) };
}

async function getEventById(key, id) {
  try {
    const one = await fetchJSON(`${espnBase(key)}/scoreboard/${encodeURIComponent(id)}`, 7000);
    if (one?.events?.[0]) return one.events[0];
    if (one?.id) return one;
  } catch {}
  const score = await getScoreboard(key);
  return score?.events?.find(e => String(e.id) === String(id)) || null;
}

async function getDetail(key, id) {
  const [event, rawStandings, live] = await Promise.all([
    getEventById(key, id),
    getStandings(key).catch(() => ({ standings: [] })),
    liveProbability(key, id),
  ]);
  if (!event) throw Object.assign(new Error('Matchup not found'), { statusCode: 404 });
  const comp = firstCompetition(event);
  const { home: hc, away: ac } = competitors(comp);
  const home = teamOf(hc), away = teamOf(ac);
  const base = await transformEvent(key, event, false);
  if (live?.home != null) base.prediction = { home: live.home, away: live.away, books: [live.source] };

  const hs = rawStandings.standings.find(x => String(x.id) === home.id || x.abbreviation === home.abbreviation);
  const as = rawStandings.standings.find(x => String(x.id) === away.id || x.abbreviation === away.abbreviation);
  const [homeRecent, awayRecent, homeInj, awayInj] = await Promise.all([
    recentGames(key, home.id), recentGames(key, away.id), injuries(key, home.id), injuries(key, away.id),
  ]);
  const homeFull = { ...home, analysis: analysisFor(hs, home), players: leaderPlayers(comp, 'home', key), recentGames: homeRecent, injuries: homeInj };
  const awayFull = { ...away, analysis: analysisFor(as, away), players: leaderPlayers(comp, 'away', key), recentGames: awayRecent, injuries: awayInj };
  return {
    fixture: {
      id: base.id, startDate: base.startDate, seasonWeek: base.seasonWeek, isLive: base.isLive,
      venue: base.venue, venueLocation: base.venueLocation, broadcast: base.broadcast,
    },
    home: homeFull,
    away: awayFull,
    prediction: base.prediction,
    spread: base.spread,
    total: base.total,
    lastUpdated: new Date().toISOString(),
  };
}

