const APP_MANIFEST = "{\"name\": \"NFL Predictor \u2014 Live Win Probabilities\", \"short_name\": \"NFL Predictor\", \"description\": \"Live NFL matchup win probabilities, odds, standings, player leaders, recent games and injuries.\", \"start_url\": \"/#/nfl\", \"scope\": \"/\", \"display\": \"standalone\", \"background_color\": \"#090b0f\", \"theme_color\": \"#090b0f\", \"orientation\": \"portrait-primary\", \"icons\": [{\"src\": \"/icon.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any maskable\"}]}";
const SERVICE_WORKER = "const CACHE='nfl-predictor-v2';\nself.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['/','/manifest.webmanifest','/icon.png'])).then(()=>self.skipWaiting())));\nself.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.pathname.startsWith('/api/')){e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));return;}e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(net=>{const cp=net.clone();caches.open(CACHE).then(c=>c.put(e.request,cp));return net;})));});\n";
const ICON_PNG = Buffer.from("", 'base64');

function sendJSON(res, status, body) {
  res.writeHead(status, { 'content-type':'application/json; charset=utf-8', 'cache-control':'no-store', 'access-control-allow-origin':'*' });
  res.end(JSON.stringify(body));
}

function serveApp(res, pathname) {
  if (pathname === '/manifest.webmanifest') { res.writeHead(200, { 'content-type':'application/manifest+json; charset=utf-8', 'cache-control':'no-cache' }); return res.end(APP_MANIFEST); }
  if (pathname === '/sw.js') { res.writeHead(200, { 'content-type':'text/javascript; charset=utf-8', 'cache-control':'no-cache' }); return res.end(SERVICE_WORKER); }
  if (pathname === '/icon.png') { res.writeHead(200, { 'content-type':'image/png', 'cache-control':'public, max-age=86400' }); return res.end(ICON_PNG); }
  res.writeHead(200, { 'content-type':'text/html; charset=utf-8', 'cache-control':'no-cache' }); return res.end(APP_HTML);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const p = url.pathname;
    if (p === '/api/health') return sendJSON(res, 200, { ok:true, time:new Date().toISOString() });
    const mList = p.match(/^\/api\/(nfl|nba|mlb)\/matchups$/);
    if (mList) return sendJSON(res, 200, await getMatchups(mList[1]));
    const mOne = p.match(/^\/api\/(nfl|nba|mlb)\/matchups\/([^/]+)$/);
    if (mOne) return sendJSON(res, 200, await getDetail(mOne[1], mOne[2]));
    const mStand = p.match(/^\/api\/(nfl|nba|mlb)\/standings$/);
    if (mStand) return sendJSON(res, 200, await getStandings(mStand[1]));
    return serveApp(res, p);
  } catch (err) {
    const status = err?.statusCode || 502;
    console.error(err);
    return sendJSON(res, status, { error: err?.message || 'Server error', hint: 'Check internet access and retry.' });
  }
});

server.listen(PORT, '0.0.0.0', () => {
  console.log(`NFL Predictor running at http://localhost:${PORT}`);
});
